d\u092a\u0937\u094d\u091f \u0915\u0930\u0924\u0947 \u0939\u0948\u0902 \u0915\u093f \u0915\u0902\u092a\u094d\u092f\u0942\u091f-\u0907\u0937\u094d\u091f\u0924\u092e \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u0928 \u0915\u0947 \u0932\u093f\u090f \u092a\u0948\u0930\u093e\u092e\u0940\u091f\u0930 \u0914\u0930 \u091f\u094b\u0915\u0928 \u0915\u094b \u0938\u092e\u093e\u0928\u0941\u092a\u093e\u0924\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u092c\u0922\u093c\u093e\u092f\u093e \u091c\u093e\u0928\u093e \u091a\u093e\u0939\u093f\u090f; \u0905\u0924\u0903 70B \u0915\u0947 \u0932\u093f\u090f \u0905\u0902\u0921\u0930\u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 \u0907\u0938\u0915\u0947 \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u0928 \u0915\u094b 13B \u0938\u0947 \u0928\u0940\u091a\u0947 \u0932\u093e \u0938\u0915\u0924\u0940 \u0939\u0948\u0964\n2. Llama-2 \u0924\u0915\u0928\u0940\u0915\u0940 \u0930\u093f\u092a\u094b\u0930\u094d\u091f (Touvron et al., 2023) \u0926\u0930\u094d\u0936\u093e\u0924\u0940 \u0939\u0948 \u0915\u093f \u092c\u093f\u0928\u093e RLHF/\u0938\u0902\u0930\u0947\u0916\u0923 \u0915\u0947 70B \u092c\u0947\u0938 \u092e\u0949\u0921\u0932 \u092e\u093e\u0928\u0935\u0940\u092f \u092a\u094d\u0930\u093e\u0925\u092e\u093f\u0915\u0924\u093e\u0913\u0902 \u0914\u0930 \u0938\u0902\u0935\u093e\u0926\u093e\u0924\u094d\u092e\u0915 \u092c\u0947\u0902\u091a\u092e\u093e\u0930\u094d\u0915 \u092e\u0947\u0902 13B-Chat \u0938\u0947 \u0915\u093e\u092b\u0940 \u092a\u0940\u091b\u0947 \u0930\u0939\u0924\u093e \u0939\u0948\u0964\n3. \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935\u093f\u0924 \u092a\u094d\u0930\u092f\u094b\u0917 \u092e\u0947\u0902 \u0921\u093f\u0915\u094b\u0921\u093f\u0902\u0917 \u091f\u0947\u092e\u094d\u092a\u0930\u0947\u091a\u0930, \u092a\u094d\u0930\u0949\u092e\u094d\u092a\u094d\u091f\u093f\u0902\u0917 \u0938\u0902\u0930\u091a\u0928\u093e, \u0921\u0940\u0915\u0902\u091f\u0948\u092e\u093f\u0928\u0947\u0936\u0928 \u0914\u0930 \u092c\u0942\u091f\u0938\u094d\u091f\u094d\u0930\u0948\u092a \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940 \u0915\u0947 \u0938\u091f\u0940\u0915 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u0936\u093e\u092e\u093f\u0932 \u0915\u093f\u090f \u0917\u090f \u0939\u0948\u0902\u0964", "answer": "# \u0938\u0902\u092a\u0942\u0930\u094d\u0923 \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0921\u093f\u091c\u093e\u0907\u0928 (Comprehensive Experimental Design)\n\n## 1. \u0936\u094b\u0927 \u0915\u093e \u0909\u0926\u094d\u0926\u0947\u0936\u094d\u092f \u0914\u0930 \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e\u090f\u0901 (Research Objective & Hypotheses)\n\n### 1.1 \u092e\u0941\u0916\u094d\u092f \u092a\u094d\u0930\u0936\u094d\u0928\n\u0915\u094d\u092f\u093e \u0915\u0947\u0935\u0932 \u092e\u0949\u0921\u0932 \u0915\u0947 \u0906\u0915\u093e\u0930 \u092e\u0947\u0902 \u0935\u0943\u0926\u094d\u0927\u093f (\u0909\u0926\u093e. Llama-2-13B \u0915\u0940 \u0924\u0941\u0932\u0928\u093e \u092e\u0947\u0902 Llama-2-70B) \u0905\u0928\u093f\u0935\u093e\u0930\u094d\u092f \u0930\u0942\u092a \u0938\u0947 \u092c\u0947\u0939\u0924\u0930 \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u0928 \u0938\u0941\u0928\u093f\u0936\u094d\u091a\u093f\u0924 \u0915\u0930\u0924\u0940 \u0939\u0948, \u092f\u093e \u0905\u092a\u0930\u094d\u092f\u093e\u092a\u094d\u0924 \u092a\u094d\u0930\u0940-\u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 (undertraining) \u0914\u0930 \u0915\u092e\u091c\u094b\u0930/\u0905\u092a\u0930\u093f\u0937\u094d\u0915\u0943\u0924 \u0938\u0902\u0930\u0947\u0916\u0923 (sub-optimal alignment) \u090f\u0915 \u092c\u0921\u093c\u0947 \u092e\u0949\u0921\u0932 \u0915\u0947 \u0938\u0902\u0930\u091a\u0928\u093e\u0924\u094d\u092e\u0915 \u0932\u093e\u092d\u094b\u0902 \u0915\u094b \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0938\u092e\u093e\u092a\u094d\u0924 \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902?\n\n### 1.2 \u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e\u090f\u0901 (Scientific Hypotheses)\n- **\u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e 1 (Chinchilla Sub-optimality Hypothesis):** \u091a\u093f\u0902\u091a\u093f\u0932\u093e \u0938\u094d\u0915\u0947\u0932\u093f\u0902\u0917 \u0928\u093f\u092f\u092e\u094b\u0902 (Hoffmann et al., 2022) \u0915\u0947 \u0905\u0928\u0941\u0938\u093e\u0930, \u092f\u0926\u093f \u090f\u0915 70B \u092e\u0949\u0921\u0932 \u0915\u094b \u092a\u0930\u094d\u092f\u093e\u092a\u094d\u0924 \u091f\u094b\u0915\u0928 (\u0915\u0902\u092a\u094d\u092f\u0942\u091f-\u0911\u092a\u094d\u091f\u093f\u092e\u0932 \u0938\u0940\u092e\u093e \u0938\u0947 \u0915\u093e\u092b\u0940 \u0915\u092e) \u092a\u0930 \u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u093f\u0924 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948, \u0924\u094b \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0938\u0948\u091a\u0941\u0930\u0947\u091f\u0947\u0921 (\u0909\u0926\u093e. 2 \u091f\u094d\u0930\u093f\u0932\u093f\u092f\u0928 \u091f\u094b\u0915\u0928) 13B \u092e\u0949\u0921\u0932 \u0924\u0925\u094d\u092f\u093e\u0924\u094d\u092e\u0915 \u0938\u091f\u0940\u0915\u0924\u093e (MMLU) \u0914\u0930 \u0917\u0923\u093f\u0924\u0940\u092f \u0924\u0930\u094d\u0915 (GSM8K) \u092e\u0947\u0902 \u0909\u0938\u0938\u0947 \u092c\u0947\u0939\u0924\u0930 \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u0928 \u0915\u0930\u0947\u0917\u093e\u0964\n- **\u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e 2 (Alignment Dominance Hypothesis):** \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0938\u0902\u0935\u093e\u0926\u093e\u0924\u094d\u092e\u0915 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 \u0914\u0930 \u091c\u091f\u093f\u0932 \u0928\u093f\u0930\u094d\u0926\u0947\u0936-\u092a\u093e\u0932\u0928 (Instruction Following) \u092e\u0947\u0902, \u0909\u091a\u094d\u091a \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0935\u093e\u0932\u0947 SFT \u0914\u0930 RLHF/DPO \u0926\u094d\u0935\u093e\u0930\u093e \u0938\u0902\u0930\u0947\u0916\u093f\u0924 13B \u092e\u0949\u0921\u0932, \u0915\u091a\u094d\u091a\u0947 (raw base) \u092f\u093e \u0916\u0930\u093e\u092c \u0924\u0930\u0940\u0915\u0947 \u0938\u0947 \u0938\u0902\u0930\u0947\u0916\u093f\u0924 70B \u092e\u0949\u0921\u0932 \u0938\u0947 \u0915\u093e\u092b\u0940 \u092c\u0947\u0939\u0924\u0930 \u092a\u0930\u093f\u0923\u093e\u092e \u0926\u0947\u0917\u093e\u0964\n- **\u092a\u0930\u093f\u0915\u0932\u094d\u092a\u0928\u093e 3 (Interaction Effect):** \u092e\u0949\u0921\u0932 \u0915\u094d\u0937\u092e\u0924\u093e = $f(\\text{Parameters}, \\text{Tokens}, \\text{Alignment Quality})$\u0964 \u092a\u0948\u0930\u093e\u092e\u0940\u091f\u0930 \u0915\u0947\u0935\u0932 \u0915\u094d\u0937\u092e\u0924\u093e \u0915\u0940 \u090a\u092a\u0930\u0940 \u0938\u0940\u092e\u093e (capacity ceiling) \u0924\u092f \u0915\u0930\u0924\u0947 \u0939\u0948\u0902; \u092a\u094d\u0930\u092d\u093e\u0935\u0940 \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u0928 \u0921\u0947\u091f\u093e-\u090f\u0915\u094d\u0938\u092a\u094b\u091c\u0930 \u0914\u0930 \u0938\u0902\u0930\u0947\u0916\u0923 \u0926\u0915\u094d\u0937\u0924\u093e \u0926\u094d\u0935\u093e\u0930\u093e \u0924\u092f \u0939\u094b\u0924\u093e \u0939\u0948\u0964\n\n---\n\n## 2. \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0930\u0942\u092a\u0930\u0947\u0916\u093e (Experimental Framework & Factorial Design)\n\n\u0939\u092e \u090f\u0915 **$2 \\times 3 \\times 3$ \u092a\u0942\u0930\u094d\u0923 \u0915\u094d\u0930\u092e\u091a\u092f (Full Factorial)** \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u092e\u0948\u091f\u094d\u0930\u093f\u0915\u094d\u0938 \u0921\u093f\u091c\u093e\u0907\u0928 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902, \u091c\u093f\u0938\u092e\u0947\u0902 \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 (\u0913\u092a\u0928 \u0935\u0947\u091f\u094d\u0938) \u0914\u0930 \u0938\u0948\u0926\u094d\u0927\u093e\u0902\u0924\u093f\u0915 (\u0928\u093f\u092f\u0902\u0924\u094d\u0930\u093f\u0924 \u092a\u094d\u0930\u0940-\u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917) \u0926\u094b\u0928\u094b\u0902 \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 \u0936\u093e\u092e\u093f\u0932 \u0939\u0948\u0902:\n\n### 2.1 \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0915\u093e\u0930\u0915 (Independent Factors)\n\n1. **\u0915\u093e\u0930\u0915 A: \u092e\u0949\u0921\u0932 \u0906\u0930\u094d\u0915\u093f\u091f\u0947\u0915\u094d\u091a\u0930\u0932 \u0938\u094d\u0915\u0947\u0932 (Model Scale)**\n   - $A_1$: 13B \u092a\u0948\u0930\u093e\u092e\u0940\u091f\u0930\u094d\u0938 (40 \u0932\u0947\u092f\u0930\u094d\u0938, 40 \u0939\u0947\u0921\u094d\u0938, 5120 \u0939\u093f\u0921\u0928 \u0921\u093e\u0907\u092e\u0947\u0902\u0936\u0928)\n   - $A_2$: 70B \u092a\u0948\u0930\u093e\u092e\u0940\u091f\u0930\u094d\u0938 (80 \u0932\u0947\u092f\u0930\u094d\u0938, 64 \u0939\u0947\u0921\u094d\u0938, 8192 \u0939\u093f\u0921\u0928 \u0921\u093e\u0907\u092e\u0947\u0902\u0936\u0928, Grouped-Query Attention)\n\n2. **\u0915\u093e\u0930\u0915 B: \u092a\u094d\u0930\u0940-\u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 \u0921\u0947\u091f\u093e \u090f\u0915\u094d\u0938\u092a\u094b\u091c\u0930 / \u091f\u094b\u0915\u0928 \u092c\u091c\u091f (Pre-training Saturation)**\n   - $B_1$ (Undertrained Regime): $200\\text{B}$ \u091f\u094b\u0915\u0928 (\u091a\u093f\u0902\u091a\u093f\u0932\u093e \u0907\u0937\u094d\u091f\u0924\u092e \u0905\u0928\u0941\u092a\u093e\u0924 \u0938\u0947 \u092c\u0939\u0941\u0924 \u0915\u092e)\n   - $B_2$ (Mid-trained Regime): $500\\text{B}\\text{\u2013}1.0\\text{T}$ \u091f\u094b\u0915\u0928\n   - $B_3$ (Fully Saturated Regime): $2.0\\text{T}$ \u091f\u094b\u0915\u0928 (Llama-2 \u092e\u093e\u0928\u0915 \u092a\u094d\u0930\u0940-\u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 \u0938\u0940\u092e\u093e)\n\n3. **\u0915\u093e\u0930\u0915 C: \u092a\u094b\u0938\u094d\u091f-\u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 \u0938\u0902\u0930\u0947\u0916\u0923 \u0938\u094d\u0925\u093f\u0924\u093f (Post-training Alignment Degree)**\n   - $C_1$ (No Alignment): \u0915\u0947\u0935\u0932 \u092a\u094d\u0930\u0940-\u091f\u094d\u0930\u0947\u0928\u094d\u0921 \u092c\u0947\u0938 \u092e\u0949\u0921\u0932 (Completion / Next-token prediction mode)\n   - $C_2$ (Sub-optimal / Noisy Alignment): \u0915\u092e-\u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e/\u0936\u094b\u0930\u092f\u0941\u0915\u094d\u0924 10k \u0928\u093f\u0930\u094d\u0926\u0947\u0936 \u0921\u0947\u091f\u093e \u092a\u0930 \u0915\u0947\u0935\u0932 1 \u092f\u0941\u0917 (epoch) \u0915\u093e \u092c\u0941\u0928\u093f\u092f\u093e\u0926\u0940 LoRA/SFT\n   - $C_3$ (Refined Alignment): \n     - *\u0935\u093f\u0915\u0932\u094d\u092a I (Llama-2 Standard):* \u0909\u091a\u094d\u091a-\u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u092a\u0930\u093f\u0937\u094d\u0915\u0943\u0924 27k SFT + \u092e\u0932\u094d\u091f\u0940-\u0938\u094d\u091f\u0947\u091c RLHF (PPO \u0906\u0927\u093e\u0930\u093f\u0924 \u0930\u093f\u091c\u0947\u0915\u094d\u0936\u0928 \u0938\u0948\u0902\u092a\u0932\u093f\u0902\u0917 + \u092a\u094d\u0930\u0949\u0915\u094d\u0938\u093f\u092e\u0932 \u092a\u0949\u0932\u093f\u0938\u0940 \u0911\u092a\u094d\u091f\u093f\u092e\u093e\u0907\u091c\u093c\u0947\u0936\u0928)\n     - *\u0935\u093f\u0915\u0932\u094d\u092a II (Modern Paradigm):* \u0909\u091a\u094d\u091a-\u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e SFT + Direct Preference Optimization (DPO)\n\n---\n\n## 3. \u0926\u094b\u0939\u0930\u0940 \u0915\u093e\u0930\u094d\u092f\u093e\u0928\u094d\u0935\u092f\u0928 \u0930\u0923\u0928\u0940\u0924\u093f (Dual Implementation Protocol)\n\n### \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 I: \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u093f\u0924 \u0938\u093f\u0902\u0925\u0947\u091f\u093f\u0915/\u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u092a\u094d\u0930\u094b\u091f\u094b\u0915\u0949\u0932 (Controlled Protocol from Scratch)\n- **\u0921\u0947\u091f\u093e\u0938\u0947\u091f:** \u0938\u092e\u093e\u0928 \u0914\u0930 \u0936\u0941\u0926\u094d\u0927 \u092a\u094d\u0930\u0940-\u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 \u0915\u0949\u0930\u094d\u092a\u0938 (\u0909\u0926\u093e. RedPajama-V2 \u092f\u093e Dolma \u0915\u093e 2T \u0938\u092c\u0938\u0947\u091f)\u0964\n- **\u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u0923 \u091a\u0947\u0915\u092a\u0949\u0907\u0902\u091f\u094d\u0938:** 13B \u0914\u0930 70B \u0926\u094b\u0928\u094b\u0902 \u0915\u094b \u0938\u092e\u093e\u0928 \u0939\u093e\u0930\u094d\u0921\u0935\u0947\u092f\u0930 \u0938\u0947\u091f\u0905\u092a (\u0909\u0926\u093e. Megatron-LM 3D Parallelism: TP+PP+DP) \u092a\u0930 \u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u093f\u0924 \u0915\u0930\u0924\u0947 \u0939\u0941\u090f \u091f\u094b\u0915\u0928 \u091a\u0947\u0915\u092a\u0949\u0907\u0902\u091f\u094d\u0938 (200B, 500B, 2T) \u0915\u094b \u092b\u094d\u0930\u0940\u091c \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964\n- **\u0938\u0902\u0930\u0947\u0916\u0923 \u092a\u094d\u0930\u092f\u094b\u0917:** \u0938\u092e\u093e\u0928 50k UltraFeedback \u0914\u0930 Llama-2-Chat SFT/Preference \u0921\u0947\u091f\u093e\u0938\u0947\u091f \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0915\u0947 $C_2$ (\u0915\u092e\u091c\u094b\u0930) \u0914\u0930 $C_3$ (\u092a\u0930\u093f\u0937\u094d\u0915\u0943\u0924 PPO/DPO) \u0935\u0947\u0930\u093f\u090f\u0902\u091f\u094d\u0938 \u092c\u0928\u093e\u090f \u091c\u093e\u0924\u0947 \u0939\u0948\u0902\u0964\n\n### \u0926\u0943\u0937\u094d\u091f\u093f\u0915\u094b\u0923 II: \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u0916\u0941\u0932\u093e \u0938\u094d\u0930\u094b\u0924 \u092a\u094d\u0930\u094b\u091f\u094b\u0915\u0949\u0932 (Practical Open-Weights Checkpoint Protocol)\n\u092f\u0926\u093f \u0938\u094d\u0915\u094d\u0930\u0948\u091a \u0938\u0947 \u092a\u094d\u0930\u0940-\u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 \u0915\u0902\u092a\u094d\u092f\u0942\u091f \u0909\u092a\u0932\u092c\u094d\u0927 \u0928 \u0939\u094b, \u0924\u094b \u092f\u0939 \u092a\u094d\u0930\u092f\u094b\u0917 \u0928\u093f\u092e\u094d\u0928\u0932\u093f\u0916\u093f\u0924 \u0938\u093e\u0930\u094d\u0935\u091c\u0928\u093f\u0915 \u092e\u0949\u0921\u0932\u094b\u0902/\u091a\u0947\u0915\u092a\u0949\u0907\u0902\u091f\u094d\u0938 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0915\u0947 \u0928\u093f\u0937\u094d\u092a\u093e\u0926\u093f\u0924 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948:\n- **\u0905\u0902\u0921\u0930-\u091f\u094d\u0930\u0947\u0928\u094d\u0921 \u092c\u0928\u093e\u092e \u092b\u0941\u0932\u0940-\u091f\u094d\u0930\u0947\u0928\u094d\u0921 \u0924\u0941\u0932\u0928\u093e:** \n  - Llama/Llama-2 \u0913\u092a\u0928 \u091a\u0947\u0915\u092a\u0949\u0907\u0902\u091f\u094d\u0938 \u0915\u0947 \u0907\u0902\u091f\u0930\u092e\u0940\u0921\u093f\u090f\u091f \u0932\u0949\u0917\u094d\u0938 \u092f\u093e \u092a\u094d\u0930\u0949\u0915\u094d\u0938\u0940 \u0906\u0930\u094d\u0915\u093f\u091f\u0947\u0915\u094d\u091a\u0930 (\u0909\u0926\u093e. Pythia \u0938\u0941\u0907\u091f: Pythia-12B at 100M/1B/300B tokens \u092c\u0928\u093e\u092e \u091b\u094b\u091f\u0947 \u092b\u0941\u0932\u0940-\u091f\u094d\u0930\u0947\u0928\u094d\u0921 \u092e\u0949\u0921\u0932) \u0905\u0925\u0935\u093e Llama-2-70B \u0915\u094b \u0938\u0940\u092e\u093f\u0924 \u091f\u094b\u0915\u0928\u094d\u0938 \u092a\u0930 \u0928\u090f \u0921\u094b\u092e\u0947\u0928 \u092e\u0947\u0902 \u092a\u094d\u0930\u0940-\u091f\u094d\u0930\u0947\u0928/\u0905\u0921\u0947\u092a\u094d\u091f \u0915\u0930\u0915\u0947 \u0924\u0941\u0932\u0928\u093e \u0915\u0930\u0928\u093e\u0964\n- **\u0938\u0902\u0930\u0947\u0916\u0923 \u0924\u0941\u0932\u0928\u093e:**\n  - $M_1$: `Llama-2-70B-Base` (\u092c\u0921\u093c\u093e \u092e\u0949\u0921\u0932, \u0915\u094b\u0908 \u0938\u0902\u0930\u0947\u0916\u0923 \u0928\u0939\u0940\u0902)\n  - $M_2$: `Llama-2-70B` + \u0915\u092e-\u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e LoRA (\u0938\u092c-\u0911\u092a\u094d\u091f\u093f\u092e\u0932 \u0905\u0932\u093e\u0907\u0928\u092e\u0947\u0902\u091f)\n  - $M_3$: `Llama-2-13B-Chat` (\u092e\u0927\u094d\u092f\u092e \u092e\u0949\u0921\u0932, \u0906\u0927\u093f\u0915\u093e\u0930\u093f\u0915 \u0930\u0942\u092a \u0938\u0947 \u092a\u0942\u0930\u094d\u0923 RLHF/PPO \u0938\u0902\u0930\u0947\u0916\u093f\u0924)\n  - $M_4$: `Llama-2-13B` + DPO (UltraFeedback \u092a\u0930\u093f\u0937\u094d\u0915\u0943\u0924 DPO \u0938\u0902\u0930\u0947\u0916\u093f\u0924)\n  - $M_5$: `Llama-2-70B-Chat` (\u090a\u092a\u0930\u0940 \u0938\u0940\u092e\u093e / Upper Bound)\n\n---\n\n## 4. \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u092e\u0947\u091f\u094d\u0930\u093f\u0915\u094d\u0938 \u0914\u0930 \u092c\u0947\u0902\u091a\u092e\u093e\u0930\u094d\u0915 \u0938\u0941\u0907\u091f (Evaluation Suite)\n\n\u092a\u094d\u0930\u092f\u094b\u0917 \u0915\u094b \u0924\u0940\u0928 \u092e\u0941\u0916\u094d\u092f \u0906\u092f\u093e\u092e\u094b\u0902 \u092e\u0947\u0902 \u0935\u093f\u092d\u093e\u091c\u093f\u0924 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948:\n\n### \u0906\u092f\u093e\u092e 1: \u092c\u0941\u0928\u093f\u092f\u093e\u0926\u0940 \u091c\u094d\u091e\u093e\u0928 \u0914\u0930 \u0924\u0930\u094d\u0915 (Factual Knowledge & Reasoning)\n- **MMLU (Massive Multitask Language Understanding):** 5-shot \u0938\u0947\u091f\u093f\u0902\u0917 \u092e\u0947\u0902 57 \u0935\u093f\u0937\u092f\u094b\u0902 \u092a\u0930 \u092c\u0939\u0941\u0935\u093f\u0915\u0932\u094d\u092a\u0940 \u0938\u091f\u0940\u0915\u0924\u093e\u0964\n- **GSM8K:** 8-shot Chain-of-Thought (CoT) \u0915\u0947 \u0938\u093e\u0925 \u0917\u0923\u093f\u0924\u0940\u092f \u0924\u0930\u094d\u0915\u0964\n- **ARC-Challenge & HellaSwag:** \u0936\u0942\u0928\u094d\u092f/\u0915\u092e-\u0936\u0949\u091f \u0915\u0949\u092e\u0928\u0938\u0947\u0902\u0938 \u0914\u0930 \u0935\u0948\u091c\u094d\u091e\u093e\u0928\u093f\u0915 \u0938\u092e\u091d\u0964\n- **HumanEval:** Pass@1 \u0915\u094b\u0921\u093f\u0902\u0917 \u0915\u094d\u0937\u092e\u0924\u093e\u0964\n\n### \u0906\u092f\u093e\u092e 2: \u0928\u093f\u0930\u094d\u0926\u0947\u0936-\u092a\u093e\u0932\u0928 \u0914\u0930 \u0938\u0902\u0935\u093e\u0926\u093e\u0924\u094d\u092e\u0915 \u0915\u094d\u0937\u092e\u0924\u093e (Instruction Following & Chat Quality)\n- **IFEval:** \u0935\u0938\u094d\u0924\u0941\u0928\u093f\u0937\u094d\u0920, \u092a\u094d\u0930\u094b\u0917\u094d\u0930\u093e\u092e\u0947\u091f\u093f\u0915 \u0928\u093f\u0930\u094d\u0926\u0947\u0936-\u092a\u093e\u0932\u0928 (\u0909\u0926\u093e. \"500 \u0936\u092c\u094d\u0926\u094b\u0902 \u092e\u0947\u0902 \u0909\u0924\u094d\u0924\u0930 \u0926\u0947\u0902\", \"JSON \u092a\u094d\u0930\u093e\u0930\u0942\u092a \u092e\u0947\u0902 \u0932\u093f\u0916\u0947\u0902\")\u0964\n- **MT-Bench:** 80 \u0926\u094b-\u091a\u0930\u0923\u0940\u092f (multi-turn) \u091c\u091f\u093f\u0932 \u092a\u094d\u0930\u0936\u094d\u0928 (\u0915\u094b\u0921\u093f\u0902\u0917, \u092d\u0942\u092e\u093f\u0915\u093e-\u0928\u093f\u092d\u093e\u0928\u093e, \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923)\u0964\n- **AlpacaEval 2.0 / Arena-Hard-Auto:** GPT-4-Turbo \u0915\u094b \u091c\u091c \u092c\u0928\u093e\u0915\u0930 \u092a\u0947\u092f\u0930\u0935\u093e\u0907\u091c \u0935\u093f\u0928-\u0930\u0947\u091f (Win Rate) \u0914\u0930 \u0932\u0947\u0902\u0925-\u092c\u093e\u092f\u0938 \u0915\u0902\u091f\u094d\u0930\u094b\u0932\u094d\u0921 \u0938\u094d\u0915\u094b\u0930 \u0915\u0940 \u0917\u0923\u0928\u093e\u0964\n\n### \u0906\u092f\u093e\u092e 3: \u0938\u0924\u094d\u092f\u0924\u093e, \u0938\u0941\u0930\u0915\u094d\u0937\u093e \u0914\u0930 \u0939\u0947\u0932\u0941\u0938\u093f\u0928\u0947\u0936\u0928 (Truthfulness & Safety)\n- **TruthfulQA (MC2 & Generative):** \u092e\u093f\u0925\u0915\u094b\u0902 \u0914\u0930 \u0917\u0932\u0924 \u0927\u093e\u0930\u0923\u093e\u0913\u0902 \u0915\u0947 \u092a\u094d\u0930\u0924\u093f \u0938\u0902\u0935\u0947\u0926\u0928\u0936\u0940\u0932\u0924\u093e\u0964\n- **ToxiGen & Red-Teaming Safety Benchmarks:** \u0939\u093e\u0928\u093f\u0915\u093e\u0930\u0915 \u092f\u093e \u0906\u092a\u0924\u094d\u0924\u093f\u091c\u0928\u0915 \u0938\u093e\u092e\u0917\u094d\u0930\u0940 \u0909\u0924\u094d\u092a\u0928\u094d\u0928 \u0915\u0930\u0928\u0947 \u0915\u0940 \u092a\u094d\u0930\u0935\u0943\u0924\u094d\u0924\u093f\u0964\n\n---\n\n## 5. \u092a\u094d\u0930\u092f\u094b\u0917\u093e\u0924\u094d\u092e\u0915 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u0914\u0930 \u0938\u0902\u092d\u093e\u0935\u093f\u0924 \u092a\u0942\u0930\u094d\u0935\u093e\u0917\u094d\u0930\u0939 \u0928\u093f\u0935\u093e\u0930\u0923 (Experimental Controls)\n\n1. **\u0921\u093f\u0915\u094b\u0921\u093f\u0902\u0917 \u092a\u0948\u0930\u093e\u092e\u0940\u091f\u0930\u094d\u0938 \u0915\u093e \u092e\u093e\u0928\u0915\u0940\u0915\u0930\u0923:**\n   - \u0924\u093e\u0930\u094d\u0915\u093f\u0915/\u0935\u0938\u094d\u0924\u0941\u0928\u093f\u0937\u094d\u0920 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 (MMLU, GSM8K, IFEval) \u0915\u0947 \u0932\u093f\u090f: Greedy Decoding (`temperature = 0.0`)\u0964\n   - \u0938\u0902\u0935\u093e\u0926\u093e\u0924\u094d\u092e\u0915 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 (MT-Bench, AlpacaEval) \u0915\u0947 \u0932\u093f\u090f: Nucleus Sampling (`temperature = 0.7, top_p = 0.9`)\u0964\n2. **\u092a\u094d\u0930\u0949\u092e\u094d\u092a\u094d\u091f \u091f\u0947\u092e\u094d\u092a\u0932\u0947\u091f \u0938\u0941\u0938\u0902\u0917\u0924\u0924\u093e (Prompt Template Strictness):**\n   - \u092c\u0947\u0938 \u092e\u0949\u0921\u0932\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f standard few-shot completion prompts\u0964\n   - \u0938\u0902\u0930\u0947\u0916\u093f\u0924 \u092e\u0949\u0921\u0932\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0906\u0927\u093f\u0915\u093e\u0930\u093f\u0915 Llama-2 Chat/Bespoke DPO \u0938\u093f\u0938\u094d\u091f\u092e \u0935 \u092f\u0942\u091c\u0930 \u092b\u0949\u0930\u094d\u092e\u0947\u091f\u094d\u0938 (\u091c\u0948\u0938\u0947 `[INST] <<SYS>>...<</SYS>>... [/INST]`)\u0964\n3. **LLM-as-a-Judge \u092a\u0942\u0930\u094d\u0935\u093e\u0917\u094d\u0930\u0939 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 (Judge Bias Mitigation):**\n   - **Position Bias:** \u0926\u094b\u0939\u0930\u0947 \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 (swapping model A and model B) \u0915\u093e \u0909\u092a\u092f\u094b\u0917\u0964\n   - **Verbosity Bias:** \u0909\u0924\u094d\u0924\u0930 \u0915\u0940 \u0932\u0902\u092c\u093e\u0908 \u0915\u094b \u0938\u093e\u092e\u093e\u0928\u094d\u092f\u0940\u0915\u0943\u0924 \u0915\u0930\u0928\u0947 \u0935\u093e\u0932\u0947 AlpacaEval 2.0 \u0932\u0947\u0902\u0925-\u0915\u0902\u091f\u094d\u0930\u094b\u0932\u094d\u0921 (LC) \u0935\u093f\u0928-\u0930\u0947\u091f \u092b\u0949\u0930\u094d\u092e\u0942\u0932\u0947 \u0915\u093e \u0909\u092a\u092f\u094b\u0917\u0964\n4. **\u0921\u0947\u091f\u093e \u0938\u0902\u0926\u0942\u0937\u0923 \u091c\u093e\u0902\u091a (Contamination Decontamination):**\n   - \u092e\u0942\u0932\u094d\u092f\u093e\u0902\u0915\u0928 \u0938\u0947\u091f\u094d\u0938 \u0915\u0947 13-\u0917\u094d\u0930\u093e\u092e \u0913\u0935\u0930\u0932\u0948\u092a \u0915\u094b \u092a\u094d\u0930\u0940-\u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 \u0914\u0930 SFT \u0921\u0947\u091f\u093e \u0938\u0947 \u092c\u093e\u0939\u0930 (filter) \u0915\u0930\u0928\u093e\u0964\n\n---\n\n## 6. \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u092f\u094b\u091c\u0928\u093e (Statistical Analysis Plan)\n\n1. **\u092e\u0941\u0916\u094d\u092f \u0914\u0930 \u0907\u0902\u091f\u0930\u0948\u0915\u094d\u0936\u0928 \u092a\u094d\u0930\u092d\u093e\u0935 (Factorial ANOVA / Linear Mixed Models):**\n   $$Y_{ijk} = \\mu + \\alpha_i (\\text{Scale}) + \\beta_j (\\text{Tokens}) + \\gamma_k (\\text{Alignment}) + (\\alpha\\beta)_{ij} + (\\alpha\\gamma)_{ik} + (\\beta\\gamma)_{jk} + \\epsilon_{ijk}$$\n   \u092f\u0939 \u091c\u093e\u0901\u091a\u0947\u0917\u093e \u0915\u093f \u0915\u094d\u092f\u093e $\\alpha$ (\u0906\u0915\u093e\u0930) \u0915\u093e \u092a\u094d\u0930\u092d\u093e\u0935 $\\beta$ (\u091f\u094b\u0915\u0928) \u092f\u093e $\\gamma$ (\u0938\u0902\u0930\u0947\u0916\u0923) \u0915\u0940 \u0905\u0928\u0941\u092a\u0938\u094d\u0925\u093f\u0924\u093f \u092e\u0947\u0902 \u0938\u093e\u0902\u0916\u094d\u092f\u093f\u0915\u0940\u092f \u0930\u0942\u092a \u0938\u0947 \u0928\u0917\u0923\u094d\u092f \u092f\u093e \u090b\u0923\u093e\u0924\u094d\u092e\u0915 \u0939\u094b \u091c\u093e\u0924\u093e \u0939\u0948\u0964\n\n2. **\u0915\u094d\u0930\u0949\u0938-\u0913\u0935\u0930 \u092c\u093f\u0902\u0926\u0941 \u0915\u0940 \u092a\u0939\u091a\u093e\u0928 (Cross-over Analysis):**\n   - \u0917\u094d\u0930\u093e\u092b $X$-\u0905\u0915\u094d\u0937 (\u092a\u094d\u0930\u0940-\u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 \u091f\u094b\u0915\u0928 / \u0905\u0932\u093e\u0907\u0928\u092e\u0947\u0902\u091f \u0938\u094d\u0915\u094b\u0930) \u092c\u0928\u093e\u092e $Y$-\u0905\u0915\u094d\u0937 (\u091f\u093e\u0938\u094d\u0915 \u0938\u094d\u0915\u094b\u0930): \n   - \u092f\u0939 \u092c\u093f\u0902\u0926\u0941 \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u093f\u0924 \u0915\u0930\u0928\u093e \u091c\u0939\u093e\u0901 `13B-FullyTrained-Aligned` \u0915\u0940 \u092a\u0930\u092b\u0949\u0930\u094d\u092e\u0947\u0902\u0938 \u0935\u0915\u094d\u0930 `70B-Undertrained` \u092f\u093e `70B-RawBase` \u0915\u094b \u092a\u093e\u0930 \u0915\u0930\u0924\u0940 \u0939\u0948 ($Score(13B_{2T, DPO}) > Score(70B_{200B, Base})$)\u0964\n\n3. **\u092e\u0939\u0924\u094d\u0935 \u092a\u0930\u0940\u0915\u094d\u0937\u0923 (Significance Testing):**\n   - \u092e\u0949\u0921\u0932 \u0906\u0909\u091f\u092a\u0941\u091f \u0915\u0947 \u092c\u0940\u091a \u0905\u0902\u0924\u0930 \u0915\u0940 \u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0947 \u0932\u093f\u090f $p < 0.01$ \u0915\u0947 \u0938\u093e\u0925 1,000-\u092a\u0941\u0928\u0930\u093e\u0935\u0943\u0924\u094d\u0924\u093f \u092c\u0942\u091f\u0938\u094d\u091f\u094d\u0930\u0948\u092a \u092a\u0941\u0928\u0930\u094d\u0928\u092e\u0942\u0928\u093e\u0915\u0930\u0923 (Bootstrap Resampling) \u0914\u0930 \u092e\u0948\u0915\u0928\u0947\u092e\u093e\u0930 \u091f\u0947\u0938\u094d\u091f (McNemar's test)\u0964\n\n---\n\n## 7. \u0905\u092a\u0947\u0915\u094d\u0937\u093f\u0924 \u092a\u0930\u093f\u0923\u093e\u092e \u0914\u0930 \u0935\u094d\u092f\u093e\u0916\u094d\u092f\u093e (Expected Outcomes & Conclusions)\n\n1. **\u0928\u0949\u0932\u0947\u091c \u0914\u0930 \u0915\u094b\u0930 \u0930\u0940\u091c\u0928\u093f\u0902\u0917 \u092e\u0947\u0902:**\n   - \u092f\u0926\u093f 70B \u092e\u0949\u0921\u0932 \u0915\u094b \u0915\u0947\u0935\u0932 200B \u091f\u094b\u0915\u0928 \u092e\u093f\u0932\u0947 \u0939\u0948\u0902, \u0924\u094b 2T \u091f\u094b\u0915\u0928 \u092a\u0930 \u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u093f\u0924 13B \u092e\u0949\u0921\u0932 MMLU \u0914\u0930 GSM8K \u092e\u0947\u0902 70B \u0915\u094b \u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0905\u0902\u0924\u0930 (\u0905\u0928\u0941\u092e\u093e\u0928\u093f\u0924 5-10% \u092e\u093e\u0930\u094d\u091c\u093f\u0928) \u0938\u0947 \u092e\u093e\u0924 \u0926\u0947\u0917\u093e\u0964 \u092f\u0939 \u0938\u093f\u0926\u094d\u0927 \u0915\u0930\u0947\u0917\u093e \u0915\u093f **\u0905\u092a\u0930\u094d\u092f\u093e\u092a\u094d\u0924 \u092a\u094d\u0930\u0940-\u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 \u092c\u0921\u093c\u0947 \u092e\u0949\u0921\u0932 \u0915\u0947 \u0932\u093e\u092d\u094b\u0902 \u0915\u094b \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0938\u092e\u093e\u092a\u094d\u0924 \u0915\u0930 \u0926\u0947\u0924\u0940 \u0939\u0948**\u0964\n2. **\u0938\u0902\u0935\u093e\u0926\u093e\u0924\u094d\u092e\u0915 \u0914\u0930 \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0909\u092a\u092f\u094b\u0917 \u092e\u0947\u0902:**\n   - 70B \u092c\u0947\u0938 \u092e\u0949\u0921\u0932 (\u0905\u0938\u0902\u0930\u0947\u0916\u093f\u0924) \u0905\u0915\u094d\u0938\u0930 \u0916\u0941\u0932\u093e \u0938\u0902\u0935\u093e\u0926 \u091c\u093e\u0930\u0940 \u0930\u0916\u0928\u0947 \u0915\u0947 \u092c\u091c\u093e\u092f \u091f\u0947\u0915\u094d\u0938\u094d\u091f \u0915\u094b \u0926\u094b\u0939\u0930\u093e\u090f\u0917\u093e \u092f\u093e \u0905\u0938\u0902\u092c\u0902\u0927\u093f\u0924 \u0938\u0902\u0926\u0930\u094d\u092d \u091c\u094b\u0921\u093c\u0947\u0917\u093e\u0964\n   - \u0907\u0938\u0915\u0947 \u0935\u093f\u092a\u0930\u0940\u0924, \u0909\u091a\u094d\u091a \u0938\u0902\u0930\u0947\u0916\u093f\u0924 13B-Chat (RLHF/PPO \u092f\u093e DPO) MT-Bench (\u0909\u0926\u093e. \u0938\u094d\u0915\u094b\u0930 ~7.0+ \u092c\u0928\u093e\u092e \u092c\u0947\u0938 \u0915\u093e <4.0) \u0914\u0930 IFEval \u092e\u0947\u0902 70B-Base \u0915\u094b \u092d\u093e\u0930\u0940 \u0905\u0902\u0924\u0930 \u0938\u0947 \u0939\u0930\u093e \u0926\u0947\u0917\u093e\u0964\n3. **\u0905\u0902\u0924\u093f\u092e \u0928\u093f\u0937\u094d\u0915\u0930\u094d\u0937:**\n   - \u092e\u0949\u0921\u0932 \u0915\u093e \u0906\u0915\u093e\u0930 (70B vs 13B) \u0915\u0947\u0935\u0932 \u090f\u0915 **\u0938\u0902\u092d\u093e\u0935\u093f\u0924 \u0915\u094d\u0937\u092e\u0924\u093e (Potential)** \u092a\u094d\u0930\u0926\u093e\u0928 \u0915\u0930\u0924\u093e \u0939\u0948; \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u0928 \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f **\u092a\u0930\u094d\u092f\u093e\u092a\u094d\u0924 \u092a\u094d\u0930\u0940-\u091f\u094d\u0930\u0947\u0928\u093f\u0902\u0917 \u091f\u094b\u0915\u0928 (Compute saturation)** \u0914\u0930 **\u0909\u091a\u094d\u091a-\u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0938\u0902\u0930\u0947\u0916\u0923 (SFT + RLHF/DPO)** \u0906\u0935\u0936\u094d\u092f\u0915 \u0914\u0930 \u0905\u0928\u093f\u0935\u093e\u0930\u094d\u092f \u0936\u0930\u094d\u0924\u0947\u0902 \u0939\u0948\u0902\u0964", "summary": "Llama-2 13B \u092c\u0928\u093e\u092e 70B \u0915\u0947 \u0932\u093f\u090f \u0938\u0902\u092a\u0942\u0930\u094d\u0923 \u091